#!/bin/sh
# The repo's deterministic checks. factory/bin/gate runs the main checkout's copy of
# this file inside a job's worktree; exit 0 means the gate passes.
# Generated by Eminzo from the files found in the repo: review it.
#
# Rust: `cargo test` builds the whole crate and runs unit, integration and doc tests; 
# No lint runs here: add `cargo clippy -- -D warnings` above the last line if the repo uses it.
# FACTORY_CHECK_MODE is "focused" while a builder iterates and "full" for the gate and the merge;
# in focused mode FACTORY_CHANGED_FILES names a file that lists the changed paths, one repo-relative
# path per line. Cargo cannot map a source file to its tests, so a focused run narrows only when
# every changed path is an integration test (tests/<name>.rs); anything else runs everything. The
# full run below is the backstop.
set -e
MODE="${FACTORY_CHECK_MODE:-full}"
CHANGED="${FACTORY_CHANGED_FILES:-}"
# Read once, then unset, so a test that starts another factory process does not inherit them.
unset FACTORY_CHECK_MODE FACTORY_CHANGED_FILES

if [ "$MODE" = focused ] && [ -n "$CHANGED" ] && [ -s "$CHANGED" ]; then
  rc=0
  grep -qvE '^tests/[^/]+\.rs$' "$CHANGED" || rc=$?
  if [ "$rc" -eq 1 ]; then
    # Only integration tests changed: run those that still exist. No selection falls through.
    set --
    while IFS= read -r f; do
      if [ -e "$f" ]; then set -- "$@" --test "$(basename "$f" .rs)"; fi
    done < "$CHANGED"
    if [ "$#" -gt 0 ]; then exec cargo test "$@"; fi
  fi
fi

cargo test
